s="px-6 py-4 text-left text-xs font-semibold">Ciudad</th><th class="px-6 py-4 text-left text-xs font-semibold">Fecha</th><th class="px-6 py-4 text-left text-xs font-semibold">Total</th><th class="px-6 py-4 text-left text-xs font-semibold">Estado</th><th class="px-6 py-4 text-right text-xs font-semibold">Acciones</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if (empty($pedidos)): ?><tr><td colspan="7" class="px-6 py-12 text-center text-slate-400">No hay pedidos registrados.</td></tr><?php else: ?><?php foreach ($pedidos as $ped):
