s="bg-slate-50"><tr><th class="px-6 py-4 text-left text-xs font-semibold">Plan</th><th class="px-6 py-4 text-left text-xs font-semibold">Precio/mes</th><th class="px-6 py-4 text-left text-xs font-semibold">Prime</th><th class="px-6 py-4 text-left text-xs font-semibold">Estado</th><th class="px-6 py-4 text-right text-xs font-semibold">Acciones</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if (empty($planes)): ?><tr><td colspan="5" class="px-6 py-12 text-center text-slate-400">No hay planes registrados.</td></tr><?php else: ?><?php foreach ($planes as $p):
