$isChecked = isset($rel_map[$prod['id']]) ? 'checked' : '';
?><label class="flex items-center gap-2 p-2 hover:bg-slate-50 rounded border border-slate-100 transition"><input type="checkbox" name="prime_productos_seleccionados[]" value="<?= $prod['id'] ?>" <?= $isChecked ?>class="w-4 h-4 text-blue-600 rounded"><span class="text-sm text-slate-700"><?= htmlspecialchars($prod['nombre']) ?></span></label><?php endforeach; ?></div></div><div id="field_tag" class="redirect_field mt-3"><input type="text" name="redirect_target_tag" class="form-input w-full rounded-lg px-3 py-2 text-sm" placeholder="Ej: mundial_2026, black_friday" value="<?= ($edit_banner['redirect_type'] ?? '') === 'tag' ? htmlspecialchars($edit_banner['redirect_target'] ?? '') : '' ?>"></div><div id="field_search" class="redirect_field mt-3"><input type="text" name="redirect_target_search" class="form-input w-full rounded-lg px-3 py-2 text-sm" placeholder="Ej: televisor 4k" value="<?= ($edit_banner['redirect_type'] ?? '') === 'search' ? htmlspecialchars($edit_banner['redirect_target'] ?? '') : '' ?>"></div></div><div class="grid grid-cols-2 gap-4"><div><label class="block text-xs font-medium mb-1">Fecha Inicio *</label><input type="date" name="fecha_inicio" required value="<?= htmlspecialchars($edit_banner['fecha_inicio'] ?? '') ?>" class="form-input w-full rounded-lg px-3 py-2 text-sm"></div><div><label class="block text-xs font-medium mb-1">Fecha Fin *</label><input type="date" name="fecha_fin" required value="<?= htmlspecialchars($edit_banner['fecha_fin'] ?? '') ?>" class="form-input w-full rounded-lg px-3 py-2 text-sm"></div></div><div class="flex items-center gap-2"><input type="checkbox" name="is_active" value="1" <?= !isset($edit_banner['is_active']) || $edit_banner['is_active'] === 't' ? 'checked' : '' ?>class="w-4 h-4"><label class="text-sm">Banner activo</label></div><div class="flex justify-end gap-3 pt-4 border-t"><a href="?module=banners" class="px-4 py-2 bg-slate-100 rounded-lg hover:bg-slate-200">Cancelar</a><button type="submit" class="btn-primary px-6 py-2 text-white rounded-lg font-medium">Guardar Banner</button></div></form></div></div><script>function toggleRedirectFields() {
const selectEl = document.getElementById('redirect_type');
if (!selectEl) return;
const type = selectEl.value;
document.querySelectorAll('.redirect_field').forEach(el =>{ el.style.display = 'none'; });
const field = document.getElementById('field_' + type);
if (field) field.style.display = 'block';
}
document.addEventListener('DOMContentLoaded', function() {
toggleRedirectFields();
const selectEl = document.getElementById('redirect_type');
if (selectEl) selectEl.addEventListener('change', toggleRedirectFields);
const bannerForm = document.querySelector('form[action*="banners&action=save_banner"], form[action*="banners&action=update_banner"]');
if (bannerForm) {
bannerForm.addEventListener('submit', function(e) {
const type = document.getElementById('redirect_type').value;
let value = ''; let isValid = true; let errorMsg = '';
if (type === 'custom') {
const input = document.querySelector('input[name="redirect_target_custom"]');
value = input ? input.value.trim() : '';
if (!value) { isValid = false; errorMsg = 'Debes ingresar una URL personalizada.'; }
} else if (type === 'category') {
const catSelect = document.querySelector('select[name="redirect_target_category"]');
const descInput = document.querySelector('input[name="category_descuento"]');
const catVal = catSelect ? catSelect.value : '';
const descVal = descInput ? descInput.value : '0';
if (!catVal) { isValid = false; errorMsg = 'Debes seleccionar una categoría.'; }
else if (!descVal || parseFloat(descVal) <= 0 || parseFloat(descVal) >100) { isValid = false; errorMsg = 'Debes indicar un porcentaje de descuento válido (1-100).'; }
else { value = catVal + '|' + descVal; }
} else if (type === 'discount') {
const discountInput = document.querySelector('input[name="redirect_target_discount"]');
value = discountInput ? discountInput.value : '';
const productosSeleccionados = document.querySelectorAll('input[name="productos_seleccionados[]"]:checked');
if (!value || parseFloat(value) <= 0 || parseFloat(value) >100) { isValid = false; errorMsg = 'Debes indicar un porcentaje de descuento válido (1-100).'; }
else if (productosSeleccionados.length === 0) { isValid = false; errorMsg = 'Debes seleccionar al menos un producto para la campaña.'; }
} else if (type === 'prime_exclusive') {
value = 'prime';
const primeProductos = document.querySelectorAll('input[name="prime_productos_seleccionados[]"]:checked');
if (primeProductos.length === 0) { isValid = false; errorMsg = 'Debes seleccionar al menos un producto Prime.'; }
} else if (type === 'tag') {
const tagInput = document.querySelector('input[name="redirect_target_tag"]');
value = tagInput ? tagInput.value.trim() : '';
if (!value) { isValid = false; errorMsg = 'Debes ingresar un nombre de tag/campaña.'; }
} else if (type === 'search') {
const searchInput = document.querySelector('input[name="redirect_target_search"]');
value = searchInput ? searchInput.value.trim() : '';
if (!value) { isValid = false; errorMsg = 'Debes ingresar un término de búsqueda.'; }
}
if (!isValid) { e.preventDefault(); emxAlert(errorMsg); return false; }
const oldHidden = bannerForm.querySelector('input[name="redirect_target"]');
if (oldHidden) oldHidden.remove();
const hidden = document.createElement('input');
hidden.type = 'hidden'; hidden.name = 'redirect_target'; hidden.value = value;
bannerForm.appendChild(hidden);
const btn = bannerForm.querySelector('button[type="submit"]');
if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>Guardando...'; }
});
}
});
</script><?php endif; ?><script>function calcIVAProd() { const precio = parseFloat(document.getElementById('precio_prod').value) || 0; const iva = parseFloat(document.getElementById('iva_prod').value) || 15; document.getElementById('precio_iva_prod').value = '$' + (precio + (precio * (iva / 100))).toFixed(2) + ' (IVA: ' + iva + '%)'; }
function addSpecRow() { const c = document.getElementById('specs_container'); c.insertAdjacentHTML('beforeend', `<div class="flex gap-2"><input type="text" name="custom_specs_keys[]" placeholder="Campo" class="form-input flex-1 rounded-lg px-3 py-2 text-sm"><input type="text" name="custom_specs_values[]" placeholder="Valor" class="form-input flex-1 rounded-lg px-3 py-2 text-sm"><button type="button" onclick="this.parentElement.remove()" class="px-3 bg-red-100 text-red-600 rounded-lg hover:bg-red-200"><i class="fas fa-trash"></i></button></div>`); }
function previewLogo(input) { const p = document.getElementById('logo_preview'); if (input.files && input.files[0]) { const r = new FileReader(); r.onload = function(e) { p.src = e.target.result; p.classList.remove('hidden'); }; r.readAsDataURL(input.files[0]); } }
function previewBanner(input) { const p = document.getElementById('banner_preview'); if (input.files && input.files[0]) { const r = new FileReader(); r.onload = function(e) { p.src = e.target.result; p.classList.remove('hidden'); }; r.readAsDataURL(input.files[0]); } }
let productoImagenesSeleccionadas = [];

function sincronizarProductoImagenesInput() {
const input = document.getElementById('producto_imagenes_input');
if (!input) return;
const dt = new DataTransfer();
productoImagenesSeleccionadas.forEach(file =>dt.items.add(file));
input.files = dt.files;
}

function agregarProductoImagenes(input) {
const nuevos = Array.from(input.files || []);
if (nuevos.length === 0) {
renderProductoImagenesPreview();
return;
}
const maxBytes = 12 * 1024 * 1024;
const permitidos = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
let rechazadas = 0;
for (const file of nuevos) {
const clave = file.name + '|' + file.size + '|' + file.lastModified;
const existe = productoImagenesSeleccionadas.some(f =>(f.name + '|' + f.size + '|' + f.lastModified) === clave);
if (existe) continue;
if (!permitidos.includes(file.type) || file.size >maxBytes) {
rechazadas++;
continue;
}
productoImagenesSeleccionadas.push(file);
}
sincronizarProductoImagenesInput();
renderProductoImagenesPreview(rechazadas);
}

function quitarProductoImagenSeleccionada(index) {
productoImagenesSeleccionadas.splice(index, 1);
sincronizarProductoImagenesInput();
renderProductoImagenesPreview();
}

function limpiarProductoImagenes() {
productoImagenesSeleccionadas = [];
sincronizarProductoImagenesInput();
renderProductoImagenesPreview();
}

function renderProductoImagenesPreview(rechazadas = 0) {
const resumen = document.getElementById('producto_imagenes_resumen');
const preview = document.getElementById('producto_imagenes_preview');
if (!resumen || !preview) return;
preview.innerHTML = '';
if (productoImagenesSeleccionadas.length === 0) {
resumen.classList.add('hidden');
preview.classList.add('hidden');
return;
}
resumen.textContent = productoImagenesSeleccionadas.length + ' imagen(es) seleccionada(s) para subir' + (rechazadas >0 ? ' · ' + rechazadas + ' omitida(s) por formato/tamaño' : '');
resumen.classList.remove('hidden');
preview.classList.remove('hidden');
productoImagenesSeleccionadas.forEach((file, index) =>{
const card = document.createElement('div');
card.className = 'relative rounded-xl overflow-hidden border border-slate-200 bg-white shadow-sm group';
const img = document.createElement('img');
img.className = 'w-full h-24 object-cover';
const remove = document.createElement('button');
remove.type = 'button';
remove.className = 'absolute top-1 right-1 w-7 h-7 bg-red-500 hover:bg-red-600 text-white rounded-full flex items-center justify-center shadow transition';
remove.innerHTML = '<i class="fas fa-times text-xs"></i>';
remove.onclick = () =>quitarProductoImagenSeleccionada(index);
const orden = document.createElement('div');
orden.className = 'absolute top-1 left-1 bg-blue-600 text-white text-[10px] font-bold px-1.5 py-0.5 rounded';
orden.textContent = index === 0 ? 'Principal' : '#' + (index + 1);
const cap = document.createElement('div');
cap.className = 'px-2 py-1 text-[10px] text-slate-600 truncate bg-slate-50';
cap.textContent = file.name;
card.appendChild(img);
card.appendChild(remove);
card.appendChild(orden);
card.appendChild(cap);
preview.appendChild(card);
const reader = new FileReader();
reader.onload = (e) =>{ img.src = e.target.result; };
reader.readAsDataURL(file);
});
}

