let contadorRangos = <?= !empty($edit_data['rangos_volumen']) ? count($edit_data['rangos_volumen']) : 0 ?>;
function agregarRangoVolumen() {
const contenedor = document.getElementById('contenedor-rangos-volumen');
const msgVacios = document.getElementById('rangos-vacios-msg');
if (msgVacios) msgVacios.classList.add('hidden');
const idx = contadorRangos++;
const nuevoRango = document.createElement('div');
nuevoRango.className = 'rango-volumen-item grid grid-cols-12 gap-2 items-end p-3 bg-purple-50 border border-purple-200 rounded-lg fade-in';
nuevoRango.innerHTML = `
<div class="col-span-2"><label class="block text-[10px] font-bold text-purple-700 mb-1">Desde (unid.)</label><input type="number" name="rangos_volumen[${idx}][cantidad_min]" min="1" required class="form-input w-full rounded px-2 py-1.5 text-sm" placeholder="Ej: 5"></div><div class="col-span-2"><label class="block text-[10px] font-bold text-purple-700 mb-1">Hasta (unid.)</label><input type="text" name="rangos_volumen[${idx}][cantidad_max]" placeholder="Vacío = ilimitado" class="form-input w-full rounded px-2 py-1.5 text-sm"></div><div class="col-span-2"><label class="block text-[10px] font-bold text-purple-700 mb-1">Descuento (%)</label><input type="number" step="0.01" min="0" max="100" required name="rangos_volumen[${idx}][descuento]" class="form-input w-full rounded px-2 py-1.5 text-sm" placeholder="Ej: 10"></div><div class="col-span-5"><label class="block text-[10px] font-bold text-purple-700 mb-1">Etiqueta (opcional)</label><input type="text" name="rangos_volumen[${idx}][etiqueta]" placeholder="Ej: Minorista, Mayorista, Distribuidor" class="form-input w-full rounded px-2 py-1.5 text-sm"></div><div class="col-span-1 flex justify-end"><button type="button" onclick="eliminarRangoVolumen(this)" class="w-8 h-8 bg-red-100 text-red-600 rounded hover:bg-red-200 transition"><i class="fas fa-trash text-xs"></i></button></div>`;
contenedor.appendChild(nuevoRango);
}
function eliminarRangoVolumen(btn) {
const item = btn.closest('.rango-volumen-item');
const contenedor = document.getElementById('contenedor-rangos-volumen');
const msgVacios = document.getElementById('rangos-vacios-msg');
item.style.transition = 'all 0.3s ease'; item.style.opacity = '0'; item.style.transform = 'translateX(20px)';
setTimeout(() =>{
item.remove();
if (contenedor.querySelectorAll('.rango-volumen-item').length === 0) { if (msgVacios) msgVacios.classList.remove('hidden'); }
}, 300);
}
// ⭐ Funciones para modal de reabastecimiento manual
function abrirModalReabastecimiento(productoId, productoNombre, stockActual, puntoReorden) {
document.getElementById('rea_producto_id').value = productoId;
document.getElementById('rea_producto_nombre').textContent = productoNombre;
document.getElementById('rea_stock_actual').textContent = stockActual + ' unid.';
document.getElementById('rea_punto_reorden').textContent = puntoReorden + ' unid.';
const sugerencia = Math.max(puntoReorden * 2 - stockActual, puntoReorden);
document.getElementById('rea_cantidad').value = sugerencia;
const fechaLimite = new Date();
fechaLimite.setDate(fechaLimite.getDate() + 7);
document.getElementById('rea_fecha_limite').value = fechaLimite.toISOString().split('T')[0];
document.getElementById('modalReabastecimiento').classList.remove('hidden');
document.body.style.overflow = 'hidden';
}
function cerrarModalReabastecimiento() {
document.getElementById('modalReabastecimiento').classList.add('hidden');
document.body.style.overflow = '';
}
